package com.example.ancapp.model

import org.json.JSONObject
import java.time.LocalDate
import java.time.Period
import java.time.format.DateTimeFormatter
import java.time.temporal.ChronoUnit

data class Patient(
    val id: String,
    val name: String,
    val dateOfBirth: String, // Format: YYYY-MM-DD
    val estimatedDueDate: String // Format: YYYY-MM-DD
) {
    /**
     * Computes the patient's age in years as of [asOfDate].
     */
    fun getAge(asOfDate: LocalDate = LocalDate.now()): Int {
        return try {
            val dob = LocalDate.parse(dateOfBirth)
            Period.between(dob, asOfDate).years
        } catch (_: Exception) {
            0
        }
    }

    /**
     * Computes gestational age in completed weeks as of [asOfDate].
     * Standard obstetric formula:
     * Full-term gestation is 40 weeks (280 days).
     * Estimated LMP = EDD - 280 days.
     * Days pregnant = days elapsed between LMP and [asOfDate].
     */
    fun getGestationalWeeks(asOfDate: LocalDate = LocalDate.now()): Int {
        return try {
            val edd = LocalDate.parse(estimatedDueDate)
            val lmp = edd.minusDays(280)
            val days = ChronoUnit.DAYS.between(lmp, asOfDate)
            (days / 7).toInt().coerceAtLeast(0)
        } catch (_: Exception) {
            0
        }
    }

    /**
     * Returns a human-friendly string for gestational age, e.g. "36 weeks" or "36 wks 4 d".
     */
    fun getGestationalAgeDisplay(asOfDate: LocalDate = LocalDate.now()): String {
        return try {
            val edd = LocalDate.parse(estimatedDueDate)
            val lmp = edd.minusDays(280)
            val days = ChronoUnit.DAYS.between(lmp, asOfDate).coerceAtLeast(0)
            val weeks = days / 7
            val remainingDays = days % 7
            if (remainingDays > 0) {
                "$weeks wks $remainingDays d"
            } else {
                "$weeks weeks"
            }
        } catch (_: Exception) {
            "0 weeks"
        }
    }

    fun getFormattedDueDate(): String {
        return try {
            val edd = LocalDate.parse(estimatedDueDate)
            edd.format(DateTimeFormatter.ofPattern("MMM d, yyyy"))
        } catch (_: Exception) {
            estimatedDueDate
        }
    }

    fun toJson(): JSONObject {
        return JSONObject().apply {
            put("id", id)
            put("name", name)
            put("dateOfBirth", dateOfBirth)
            put("estimatedDueDate", estimatedDueDate)
        }
    }

    companion object {
        fun fromJson(json: JSONObject): Patient {
            return Patient(
                id = json.getString("id"),
                name = json.getString("name"),
                dateOfBirth = json.getString("dateOfBirth"),
                estimatedDueDate = json.getString("estimatedDueDate")
            )
        }
    }
}

package com.example.ancapp.model

import org.json.JSONArray
import org.json.JSONObject
import java.time.LocalDate
import java.time.format.DateTimeFormatter

object DangerSigns {
    const val NONE = "None"
    const val VAGINAL_BLEEDING = "Vaginal bleeding"
    const val SEVERE_HEADACHE = "Severe headache"
    const val BLURRED_VISION = "Blurred vision"
    const val FEVER = "Fever"

    val ALL = listOf(
        NONE,
        VAGINAL_BLEEDING,
        SEVERE_HEADACHE,
        BLURRED_VISION,
        FEVER
    )
}

data class AncVisit(
    val id: String,
    val patientId: String,
    val date: String, // Format: YYYY-MM-DD
    val gestationalAgeWeeks: Int,
    val weightKg: Double,
    val systolicBp: Int,
    val diastolicBp: Int,
    val hemoglobin: Double? = null, // g/dL, optional
    val dangerSigns: List<String> = listOf(DangerSigns.NONE),
    val notes: String = ""
) {
    val bloodPressureDisplay: String
        get() = "$systolicBp/$diastolicBp mmHg"

    val weightDisplay: String
        get() = "$weightKg kg"

    val hemoglobinDisplay: String?
        get() = hemoglobin?.let { "$it g/dL" }

    fun getFormattedDate(): String {
        return try {
            val d = LocalDate.parse(date)
            d.format(DateTimeFormatter.ofPattern("MMM d, yyyy"))
        } catch (_: Exception) {
            date
        }
    }

    val hasCriticalDangerSigns: Boolean
        get() = dangerSigns.any { it != DangerSigns.NONE }

    fun toJson(): JSONObject {
        return JSONObject().apply {
            put("id", id)
            put("patientId", patientId)
            put("date", date)
            put("gestationalAgeWeeks", gestationalAgeWeeks)
            put("weightKg", weightKg)
            put("systolicBp", systolicBp)
            put("diastolicBp", diastolicBp)
            if (hemoglobin != null) {
                put("hemoglobin", hemoglobin)
            } else {
                put("hemoglobin", JSONObject.NULL)
            }
            val signsArray = JSONArray()
            dangerSigns.forEach { signsArray.put(it) }
            put("dangerSigns", signsArray)
            put("notes", notes)
        }
    }

    companion object {
        fun fromJson(json: JSONObject): AncVisit {
            val signsList = mutableListOf<String>()
            val signsArray = json.optJSONArray("dangerSigns")
            if (signsArray != null) {
                for (i in 0 until signsArray.length()) {
                    signsList.add(signsArray.getString(i))
                }
            }
            if (signsList.isEmpty()) {
                signsList.add(DangerSigns.NONE)
            }

            val hb = if (json.has("hemoglobin") && !json.isNull("hemoglobin")) {
                json.getDouble("hemoglobin")
            } else {
                null
            }

            return AncVisit(
                id = json.getString("id"),
                patientId = json.getString("patientId"),
                date = json.getString("date"),
                gestationalAgeWeeks = json.getInt("gestationalAgeWeeks"),
                weightKg = json.getDouble("weightKg"),
                systolicBp = json.getInt("systolicBp"),
                diastolicBp = json.getInt("diastolicBp"),
                hemoglobin = hb,
                dangerSigns = signsList,
                notes = json.optString("notes", "")
            )
        }
    }
}

package com.example.ancapp.data

import android.content.Context
import com.example.ancapp.model.AncVisit
import com.example.ancapp.model.DangerSigns
import com.example.ancapp.model.Patient
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import org.json.JSONArray
import org.json.JSONObject
import java.io.File
import java.time.LocalDate

class AncRepository(private val context: Context) {

    private val dataFile: File by lazy {
        File(context.filesDir, "anc_data.json")
    }

    private val _patients = MutableStateFlow<List<Patient>>(emptyList())
    val patients: StateFlow<List<Patient>> = _patients.asStateFlow()

    private val _visits = MutableStateFlow<List<AncVisit>>(emptyList())
    val visits: StateFlow<List<AncVisit>> = _visits.asStateFlow()

    init {
        loadData()
    }

    @Synchronized
    private fun loadData() {
        if (!dataFile.exists()) {
            val initialPatients = createSeedPatients()
            val initialVisits = createSeedVisits()
            _patients.value = initialPatients
            _visits.value = initialVisits
            persistToDisk(initialPatients, initialVisits)
        } else {
            try {
                val jsonString = dataFile.readText()
                val root = JSONObject(jsonString)

                val loadedPatients = mutableListOf<Patient>()
                val patientsArray = root.optJSONArray("patients") ?: JSONArray()
                for (i in 0 until patientsArray.length()) {
                    loadedPatients.add(Patient.fromJson(patientsArray.getJSONObject(i)))
                }

                val loadedVisits = mutableListOf<AncVisit>()
                val visitsArray = root.optJSONArray("visits") ?: JSONArray()
                for (i in 0 until visitsArray.length()) {
                    loadedVisits.add(AncVisit.fromJson(visitsArray.getJSONObject(i)))
                }

                _patients.value = loadedPatients
                _visits.value = loadedVisits
            } catch (e: Exception) {
                e.printStackTrace()
                // Fallback to seed data if corrupted
                val fallbackPatients = createSeedPatients()
                val fallbackVisits = createSeedVisits()
                _patients.value = fallbackPatients
                _visits.value = fallbackVisits
                persistToDisk(fallbackPatients, fallbackVisits)
            }
        }
    }

    @Synchronized
    private fun persistToDisk(patientsList: List<Patient>, visitsList: List<AncVisit>) {
        try {
            val root = JSONObject()
            val patientsArray = JSONArray()
            patientsList.forEach { patientsArray.put(it.toJson()) }
            root.put("patients", patientsArray)

            val visitsArray = JSONArray()
            visitsList.forEach { visitsArray.put(it.toJson()) }
            root.put("visits", visitsArray)

            val tempFile = File(context.filesDir, "anc_data.json.tmp")
            tempFile.writeText(root.toString(2))
            tempFile.renameTo(dataFile)
        } catch (e: Exception) {
            e.printStackTrace()
        }
    }

    fun getPatientsSortedByDueDate(): List<Patient> {
        return _patients.value.sortedWith(Comparator { p1, p2 ->
            try {
                val d1 = LocalDate.parse(p1.estimatedDueDate)
                val d2 = LocalDate.parse(p2.estimatedDueDate)
                d1.compareTo(d2)
            } catch (_: Exception) {
                p1.estimatedDueDate.compareTo(p2.estimatedDueDate)
            }
        })
    }

    fun getPatientById(patientId: String): Patient? {
        return _patients.value.find { it.id == patientId }
    }

    fun getVisitsForPatient(patientId: String): List<AncVisit> {
        return _visits.value
            .filter { it.patientId == patientId }
            .sortedWith(Comparator { v1, v2 ->
                try {
                    val d1 = LocalDate.parse(v1.date)
                    val d2 = LocalDate.parse(v2.date)
                    // Newest visits first
                    d2.compareTo(d1)
                } catch (_: Exception) {
                    v2.date.compareTo(v1.date)
                }
            })
    }

    @Synchronized
    fun addVisit(visit: AncVisit) {
        val updatedVisits = _visits.value + visit
        _visits.value = updatedVisits
        persistToDisk(_patients.value, updatedVisits)
    }

    @Synchronized
    fun addPatient(patient: Patient) {
        val updatedPatients = _patients.value + patient
        _patients.value = updatedPatients
        persistToDisk(updatedPatients, _visits.value)
    }

    companion object {
        fun createSeedPatients(): List<Patient> {
            return listOf(
                Patient(
                    id = "patient-emily-carter",
                    name = "Emily Carter",
                    dateOfBirth = "1996-04-12",
                    estimatedDueDate = "2026-12-05"
                ),
                Patient(
                    id = "patient-sarah-mitchell",
                    name = "Sarah Mitchell",
                    dateOfBirth = "1990-11-02",
                    estimatedDueDate = "2027-01-20"
                ),
                Patient(
                    id = "patient-grace-thompson",
                    name = "Grace Thompson",
                    dateOfBirth = "2001-07-30",
                    estimatedDueDate = "2026-10-15"
                )
            )
        }

        fun createSeedVisits(): List<AncVisit> {
            return listOf(
                AncVisit(
                    id = "visit-emily-1",
                    patientId = "patient-emily-carter",
                    date = "2026-08-10",
                    gestationalAgeWeeks = 23,
                    weightKg = 68.5,
                    systolicBp = 118,
                    diastolicBp = 76,
                    hemoglobin = 11.8,
                    dangerSigns = listOf(DangerSigns.NONE),
                    notes = "Routine antenatal checkup. Fetal heartbeat detected, normal progression."
                ),
                AncVisit(
                    id = "visit-sarah-1",
                    patientId = "patient-sarah-mitchell",
                    date = "2026-08-12",
                    gestationalAgeWeeks = 17,
                    weightKg = 61.2,
                    systolicBp = 110,
                    diastolicBp = 70,
                    hemoglobin = 12.4,
                    dangerSigns = listOf(DangerSigns.NONE),
                    notes = "Initial second trimester assessment. Prenatal vitamins continued."
                ),
                AncVisit(
                    id = "visit-grace-1",
                    patientId = "patient-grace-thompson",
                    date = "2026-08-05",
                    gestationalAgeWeeks = 29,
                    weightKg = 72.0,
                    systolicBp = 128,
                    diastolicBp = 84,
                    hemoglobin = 10.2,
                    dangerSigns = listOf(DangerSigns.NONE),
                    notes = "Mild anemia observed. Prescribed oral iron and folic acid supplements."
                )
            )
        }
    }
}

package com.example.ancapp.ui

import android.app.Application
import androidx.lifecycle.AndroidViewModel
import androidx.lifecycle.viewModelScope
import com.example.ancapp.data.AncRepository
import com.example.ancapp.model.AncVisit
import com.example.ancapp.model.Patient
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.SharingStarted
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.combine
import kotlinx.coroutines.flow.stateIn
import java.util.UUID

sealed interface Screen {
    object Register : Screen
    data class PatientDetail(val patientId: String) : Screen
    data class RecordVisit(val patientId: String) : Screen
}

class AncViewModel(application: Application) : AndroidViewModel(application) {

    private val repository = AncRepository(application.applicationContext)

    private val _currentScreen = MutableStateFlow<Screen>(Screen.Register)
    val currentScreen: StateFlow<Screen> = _currentScreen.asStateFlow()

    // Sorted by due date (soonest first)
    val patients: StateFlow<List<Patient>> = repository.patients
        .combine(MutableStateFlow(Unit)) { patients, _ ->
            patients.sortedWith { p1, p2 ->
                p1.estimatedDueDate.compareTo(p2.estimatedDueDate)
            }
        }.stateIn(
            scope = viewModelScope,
            started = SharingStarted.WhileSubscribed(5000),
            initialValue = repository.getPatientsSortedByDueDate()
        )

    val visits: StateFlow<List<AncVisit>> = repository.visits

    fun navigateToRegister() {
        _currentScreen.value = Screen.Register
    }

    fun navigateToPatientDetail(patientId: String) {
        _currentScreen.value = Screen.PatientDetail(patientId)
    }

    fun navigateToRecordVisit(patientId: String) {
        _currentScreen.value = Screen.RecordVisit(patientId)
    }

    fun getPatient(patientId: String): Patient? {
        return repository.getPatientById(patientId)
    }

    fun getVisitsForPatient(patientId: String): List<AncVisit> {
        return repository.getVisitsForPatient(patientId)
    }

    fun recordVisit(
        patientId: String,
        date: String,
        gestationalAgeWeeks: Int,
        weightKg: Double,
        systolicBp: Int,
        diastolicBp: Int,
        hemoglobin: Double?,
        dangerSigns: List<String>,
        notes: String
    ): AncVisit {
        val newVisit = AncVisit(
            id = "visit-${UUID.randomUUID()}",
            patientId = patientId,
            date = date,
            gestationalAgeWeeks = gestationalAgeWeeks,
            weightKg = weightKg,
            systolicBp = systolicBp,
            diastolicBp = diastolicBp,
            hemoglobin = hemoglobin,
            dangerSigns = dangerSigns,
            notes = notes
        )
        repository.addVisit(newVisit)
        return newVisit
    }

    fun addPatient(name: String, dateOfBirth: String, estimatedDueDate: String): Patient {
        val newPatient = Patient(
            id = "patient-${UUID.randomUUID()}",
            name = name,
            dateOfBirth = dateOfBirth,
            estimatedDueDate = estimatedDueDate
        )
        repository.addPatient(newPatient)
        return newPatient
    }
}

