@Composable
fun AddPatientDialog(
    onDismiss: () -> Unit,
    onConfirm: (name: String, dob: String, edd: String) -> Unit
) {
    var name by remember { mutableStateOf("") }
    var dob by remember { mutableStateOf("") }
    var edd by remember { mutableStateOf("") }
    var errorMessage by remember { mutableStateOf<String?>(null) }

    AlertDialog(
        onDismissRequest = onDismiss,
        title = {
            Text(
                text = "Enroll New Patient",
                style = MaterialTheme.typography.titleLarge
            )
        },
        text = {
            Column(modifier = Modifier.fillMaxWidth()) {
                OutlinedTextField(
                    value = name,
                    onValueChange = {
                        name = it
                        errorMessage = null
                    },
                    label = { Text("Full Name") },
                    singleLine = true,
                    modifier = Modifier.fillMaxWidth(),
                    keyboardOptions = KeyboardOptions(imeAction = ImeAction.Next)
                )

                Spacer(modifier = Modifier.height(8.dp))

                OutlinedTextField(
                    value = dob,
                    onValueChange = {
                        dob = it
                        errorMessage = null
                    },
                    label = { Text("Date of Birth (YYYY-MM-DD)") },
                    placeholder = { Text("e.g. 1998-05-20") },
                    singleLine = true,
                    modifier = Modifier.fillMaxWidth(),
                    keyboardOptions = KeyboardOptions(
                        keyboardType = KeyboardType.Number,
                        imeAction = ImeAction.Next
                    )
                )

                Spacer(modifier = Modifier.height(8.dp))

                OutlinedTextField(
                    value = edd,
                    onValueChange = {
                        edd = it
                        errorMessage = null
                    },
                    label = { Text("Estimated Due Date (YYYY-MM-DD)") },
                    placeholder = { Text("e.g. 2027-02-15") },
                    singleLine = true,
                    modifier = Modifier.fillMaxWidth(),
                    keyboardOptions = KeyboardOptions(
                        keyboardType = KeyboardType.Number,
                        imeAction = ImeAction.Done
                    )
                )

                if (errorMessage != null) {
                    Spacer(modifier = Modifier.height(8.dp))
                    Text(
                        text = errorMessage!!,
                        color = MaterialTheme.colorScheme.error,
                        style = MaterialTheme.typography.bodySmall
                    )
                }
            }
        },
        confirmButton = {
            Button(
                onClick = {
                    val trimmedName = name.trim()
                    val trimmedDob = dob.trim()
                    val trimmedEdd = edd.trim()

                    if (trimmedName.isEmpty()) {
                        errorMessage = "Please enter patient name"
                        return@Button
                    }
                    try {
                        LocalDate.parse(trimmedDob)
                    } catch (_: Exception) {
                        errorMessage = "Invalid DOB format. Use YYYY-MM-DD"
                        return@Button
                    }
                    try {
                        LocalDate.parse(trimmedEdd)
                    } catch (_: Exception) {
                        errorMessage = "Invalid Due Date format. Use YYYY-MM-DD"
                        return@Button
                    }

                    onConfirm(trimmedName, trimmedDob, trimmedEdd)
                }
            ) {
                Text("Enroll")
            }
        },
        dismissButton = {
            TextButton(onClick = onDismiss) {
                Text("Cancel")
            }
        }
    )
}

